function contextLabels() {
    const {level,modules,period,year,project} = spreadsheet().context();
    const grade = {'7':'Sétimo año','8':'Octavo año','9':'Noveno año'}[String(level).match(/^[789]/)?.[0]];
    const term = [period==='I'||period==='II'?period+' período':'',year].filter(Boolean).join(' ');
    const details = [grade,modules.join(' y '),term].filter(Boolean);
    const name = String(project||'').replace(/[\u0000-\u0020]+/g,' ').trim();
    const caption = name ? 'Proyecto de Secundaria «'+name+'»' : 'Proyecto de Secundaria';
    return [
        ['PNFT','Formación Tecnológica','Proyecto de Secundaria',...details].join(' · '),
        [caption,'PNFT',...details].join(' · ')
    ];
}
